def _blocks(hint: str) -> tuple:
    """Split ``$…$`` into math blocks and the rest into text blocks."""
    out = []
    for i, part in enumerate(re.split(r"\$([^$]+)\$", hint)):
        if not part:
            continue
        out.append(math(part) if i % 2 else text(part))
    return tuple(out)


def apply_math_hints() -> int:
    for key, hint in MATH_HINTS.items():
        REGISTRY[key].stage_hint = _blocks(hint)
    return len(MATH_HINTS)


APPLIED_MATH_HINTS = apply_math_hints()
